/**
 * Pure renderers for the token artifacts. Every generated file in the token layer is produced
 * here from `src/tokens/source.ts` — `theme.css`, `fonts.css` and `tailwind.preset.ts` are build
 * artifacts (`packages/ui/AGENTS.md`), regenerated by `src/tokens/generate.ts` and committed;
 * they are never hand-edited.
 *
 * The renderers take the token module as a parameter instead of importing it so the same code
 * runs identically under the Node CLI (which needs explicit `.ts` specifiers), under Vitest and
 * under `tsc`, while this file itself stays free of runtime imports.
 */
import type * as Source from './source';

/** The token module's shape, as consumed by the renderers. */
export type TokenSource = typeof Source;

const SPACING_CSS: Readonly<Record<keyof typeof Source.spacing, string>> = {
  xs: 'space-xs',
  sm: 'space-sm',
  md: 'space-md',
  lg: 'space-lg',
  xl: 'space-xl',
  '2xl': 'space-2xl',
};

const SIZING_CSS: Readonly<Record<keyof typeof Source.sizing, string>> = {
  'button-height': 'button-height',
  'input-height': 'input-height',
  'icon-size': 'icon-size',
};

const HEADER =
  '/* GENERATED from packages/ui/src/tokens/source.ts by src/tokens/generate.ts — the transcription\n' +
  '   of docs/OyoDigitalParliament/branding.md. Never hand-edit; regenerate with\n' +
  '   `node src/tokens/generate.ts` from packages/ui. */\n';

const colorVar = (family: Source.ColorFamilyName, shade: Source.ColorShade): string =>
  `--odp-color-${family}-${shade}`;

/** Render `src/styles/theme.css`: the custom properties for both columns plus the Tailwind mapping. */
export function renderThemeCss(source: TokenSource): string {
  const out: string[] = [];
  out.push(HEADER);
  out.push(
    '\n/* Consumed as: @import "@odp/ui/styles/theme.css"; after @import "tailwindcss";\n' +
      '   Mode selection: the light column is the root; prefers-color-scheme: dark switches to the\n' +
      '   dark column, overridable in both directions with data-theme="light"/"dark" on <html>.\n' +
      '   Device values: mobile is the base; tablet and desktop override at the branding breakpoints. */\n\n',
  );

  out.push(':root {\n  color-scheme: light;\n');

  out.push('\n  /* Colour palette — light column (branding.md, Color Palette). */\n');
  for (const family of source.declaredFamilies) {
    for (const shade of source.declaredShades) {
      out.push(`  ${colorVar(family, shade)}: ${source.colorFamilies[family][shade].light};\n`);
    }
  }

  out.push(
    '\n  /* Structural role mappings (branding.md) — resolved by reference, so both columns hold. */\n',
  );
  for (const [role, mapped] of Object.entries(source.structuralRoles)) {
    out.push(`  --odp-${role}: var(${colorVar(mapped.family, mapped.shade)});\n`);
  }

  out.push('\n  /* Typography (branding.md, Font Family and Type Scale). */\n');
  for (const [role, family] of Object.entries(source.fontFamilies)) {
    out.push(`  --odp-font-${role}: ${family.stack};\n`);
  }
  for (const [token, spec] of Object.entries(source.typeScale)) {
    out.push(`  --odp-font-size-${token}: ${spec.sizes.mobile}px;\n`);
    out.push(`  --odp-line-height-${token}: ${spec.lineHeight};\n`);
    out.push(`  --odp-font-weight-${token}: ${spec.weight};\n`);
  }

  out.push('\n  /* Spacing (branding.md) — mobile base. */\n');
  for (const token of Object.keys(SPACING_CSS) as (keyof typeof SPACING_CSS)[]) {
    out.push(`  --odp-${SPACING_CSS[token]}: ${source.spacing[token].mobile}px;\n`);
  }

  out.push('\n  /* Interactive sizing (branding.md, Scales by device) — mobile base. */\n');
  for (const token of Object.keys(SIZING_CSS) as (keyof typeof SIZING_CSS)[]) {
    out.push(`  --odp-${SIZING_CSS[token]}: ${source.sizing[token].mobile}px;\n`);
  }

  out.push(
    '\n  /* Radii, border and focus treatment (branding.md, Sizing: Fixed; Accessibility). */\n',
  );
  for (const [token, value] of Object.entries(source.radii)) {
    out.push(`  --odp-radius-${token}: ${value}px;\n`);
  }
  out.push(`  --odp-border-width: ${source.borderWidth}px;\n`);
  const focus = source.focusTreatment;
  out.push(`  --odp-focus-ring-color: var(${colorVar(focus.color.family, focus.color.shade)});\n`);
  out.push(`  --odp-focus-width: ${focus.width}px;\n`);
  out.push(`  --odp-focus-offset: ${focus.offset}px;\n`);

  out.push('\n  /* Shadows — light column (branding.md, Shadows). */\n');
  for (const [token, value] of Object.entries(source.shadows)) {
    out.push(`  --odp-shadow-${token}: ${value.light};\n`);
  }
  out.push('}\n');

  // Dark column, emitted twice: once for the OS preference (excluding an explicit light override)
  // and once for an explicit dark override on <html>, so both selection paths work.
  const darkBlock = (openSelector: string, closeBraces: number, indent: string): string[] => {
    const block: string[] = [];
    block.push(openSelector + ' {\n');
    block.push(indent + 'color-scheme: dark;\n');
    block.push(`\n${indent}/* Colour palette — dark column. */\n`);
    for (const family of source.declaredFamilies) {
      for (const shade of source.declaredShades) {
        block.push(
          `${indent}${colorVar(family, shade)}: ${source.colorFamilies[family][shade].dark};\n`,
        );
      }
    }
    block.push(`\n${indent}/* Shadows — dark column. */\n`);
    for (const [token, value] of Object.entries(source.shadows)) {
      block.push(`${indent}--odp-shadow-${token}: ${value.dark};\n`);
    }
    block.push(
      indent + '}'.repeat(1) + '\n' + '}'.repeat(closeBraces - 1) + (closeBraces > 1 ? '\n' : ''),
    );
    return block;
  };
  for (const line of darkBlock(
    '@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"])',
    2,
    '    ',
  )) {
    out.push(line);
  }
  out.push('\n');
  for (const line of darkBlock('[data-theme="dark"]', 1, '  ')) {
    out.push(line);
  }

  out.push('\n');
  for (const [device, width] of Object.entries(source.breakpoints)) {
    out.push(`@media (min-width: ${width}px) {\n  :root {\n`);
    out.push(`    /* ${device} values (branding.md, Responsive & Device Targets). */\n`);
    for (const [token, spec] of Object.entries(source.typeScale)) {
      out.push(`    --odp-font-size-${token}: ${spec.sizes[device as Source.DeviceClass]}px;\n`);
    }
    for (const token of Object.keys(SPACING_CSS) as (keyof typeof SPACING_CSS)[]) {
      out.push(
        `    --odp-${SPACING_CSS[token]}: ${source.spacing[token][device as Source.DeviceClass]}px;\n`,
      );
    }
    for (const token of Object.keys(SIZING_CSS) as (keyof typeof SIZING_CSS)[]) {
      out.push(
        `    --odp-${SIZING_CSS[token]}: ${source.sizing[token][device as Source.DeviceClass]}px;\n`,
      );
    }
    out.push('  }\n}\n\n');
  }

  out.push(renderTailwindTheme(source));
  return out.join('');
}

/** The Tailwind v4 `@theme inline` block: every scale maps onto the custom properties above. */
function renderTailwindTheme(source: TokenSource): string {
  const out: string[] = [];
  out.push(
    '/* Tailwind v4 mapping. The `inline` keyword keeps the var() reference inside each utility,\n' +
      '   so utilities track the light/dark and device values without dark: variants or arbitrary\n' +
      '   values. Default scale namespaces are reset so only branding tokens resolve. */\n',
  );
  out.push('@theme inline {\n');

  const resets = [
    '--color-*: initial',
    '--font-*: initial',
    '--text-*: initial',
    '--spacing-*: initial',
    '--spacing: initial',
    '--breakpoint-*: initial',
    '--container-*: initial',
    '--radius-*: initial',
    '--shadow-*: initial',
    '--leading-*: initial',
    '--tracking-*: initial',
    '--ease-*: initial',
  ];
  for (const reset of resets) {
    out.push(`  ${reset};\n`);
  }

  out.push(
    '\n  /* Breakpoints (branding.md, Responsive & Device Targets); mobile needs no variant. */\n',
  );
  for (const [device, width] of Object.entries(source.breakpoints)) {
    out.push(`  --breakpoint-${device}: ${width}px;\n`);
  }

  out.push('\n  /* Colour palette. */\n');
  for (const family of source.declaredFamilies) {
    for (const shade of source.declaredShades) {
      out.push(`  --color-${family}-${shade}: var(${colorVar(family, shade)});\n`);
    }
  }
  out.push('\n  /* Structural roles. */\n');
  for (const role of Object.keys(source.structuralRoles)) {
    if (role === 'theme-color') continue;
    out.push(`  --color-${role}: var(--odp-${role});\n`);
  }
  // The theme-color role serves the <meta name="theme-color"> tag; exposed under a short name.
  out.push('  --color-theme: var(--odp-theme-color);\n');

  out.push('\n  /* Font families; the body family is the preflight default. */\n');
  for (const role of Object.keys(source.fontFamilies)) {
    out.push(`  --font-${role}: var(--odp-font-${role});\n`);
  }
  out.push('  --default-font-family: var(--odp-font-body);\n');

  out.push('\n  /* Type scale, with its line height and weight attached. */\n');
  for (const token of Object.keys(source.typeScale)) {
    out.push(`  --text-${token}: var(--odp-font-size-${token});\n`);
    out.push(`  --text-${token}--line-height: var(--odp-line-height-${token});\n`);
    out.push(`  --text-${token}--font-weight: var(--odp-font-weight-${token});\n`);
  }

  out.push(
    '\n  /* Spacing, plus the interactive heights as spacing names for the h, min-h and size utilities. */\n',
  );
  for (const token of Object.keys(SPACING_CSS) as (keyof typeof SPACING_CSS)[]) {
    out.push(`  --spacing-${token}: var(--odp-${SPACING_CSS[token]});\n`);
  }
  out.push('  --spacing-button: var(--odp-button-height);\n');
  out.push('  --spacing-input: var(--odp-input-height);\n');
  out.push('  --spacing-icon: var(--odp-icon-size);\n');

  out.push('\n  /* Radii and shadows. */\n');
  for (const [token] of Object.entries(source.radii)) {
    out.push(`  --radius-${token}: var(--odp-radius-${token});\n`);
  }
  for (const [token] of Object.entries(source.shadows)) {
    out.push(`  --shadow-${token}: var(--odp-shadow-${token});\n`);
  }

  out.push('}\n');
  return out.join('');
}

/** Render `src/styles/fonts.css`: the @font-face rules for slots A-042 and A-043. */
export function renderFontsCss(source: TokenSource): string {
  const out: string[] = [];
  out.push(HEADER);
  out.push(
    '\n/* Font faces for the two font slots (assets/ASSETS.md, Family: Font — Noto Sans and Noto\n' +
      "   Serif, variable WOFF2, SIL OFL 1.1). Coverage of Yoruba's sub-dotted vowels and tone marks\n" +
      '   is the reason these families were chosen, so a subset that drops them is a defect.\n' +
      '   The deployable serves the slot files at /fonts/ (the assets directory itself is never\n' +
      '   served directly); a missing slot file is reported, not substituted. */\n\n',
  );
  for (const [role, asset] of Object.entries(source.fontAssets)) {
    const family = role === 'display' ? 'Noto Serif' : 'Noto Sans';
    out.push(`@font-face {\n`);
    out.push(`  font-family: "${family}";\n`);
    out.push(`  src: url("${asset.publicPath}") format("woff2");\n`);
    out.push(`  font-weight: ${asset.weightRange};\n`);
    out.push('  font-style: normal;\n');
    out.push('  font-display: swap;\n');
    out.push(`  /* Slot ${asset.slot}: ${asset.file} */\n`);
    out.push('}\n\n');
  }
  return out.join('');
}

/** Render `tailwind.preset.ts`: the same scales as a Tailwind preset for config-driven consumers. */
export function renderPresetTs(source: TokenSource): string {
  const out: string[] = [];
  out.push('/**\n');
  out.push(' * GENERATED from packages/ui/src/tokens/source.ts by src/tokens/generate.ts — the\n');
  out.push(
    ' * transcription of docs/OyoDigitalParliament/branding.md. Never hand-edit; regenerate with\n',
  );
  out.push(' * `node src/tokens/generate.ts` from packages/ui.\n');
  out.push(' *\n');
  out.push(
    " * Maps Tailwind's colour, typography, spacing, radius, border and shadow scales onto the\n",
  );
  out.push(
    ' * custom properties that src/styles/theme.css defines, so a component never needs an\n',
  );
  out.push(' * arbitrary value. Canonical Tailwind v4 consumption is the CSS import:\n');
  out.push(' *\n');
  out.push(' *   @import "tailwindcss";\n');
  out.push(' *   @import "@odp/ui/styles/theme.css";\n');
  out.push(' *\n');
  out.push(
    ' * This preset serves config-driven consumers through `@config "@odp/ui/tailwind.preset";`.\n',
  );
  out.push(
    " * The screens here replace Tailwind's defaults so only the branding breakpoints resolve:\n",
  );
  out.push(' * mobile is the base, `tablet:` starts at 640px, `desktop:` at 1024px.\n');
  out.push(' */\n\n');
  out.push('const theme = {\n');
  out.push('  theme: {\n');
  out.push('    screens: {\n');
  for (const [device, width] of Object.entries(source.breakpoints)) {
    out.push(`      ${device}: "${width}px",\n`);
  }
  out.push('    },\n');
  out.push('    extend: {\n');

  out.push('      colors: {\n');
  for (const family of source.declaredFamilies) {
    out.push(`        ${family}: {\n`);
    for (const shade of source.declaredShades) {
      out.push(`          ${shade}: "var(${colorVar(family, shade)})",\n`);
    }
    out.push('        },\n');
  }
  for (const role of Object.keys(source.structuralRoles)) {
    if (role === 'theme-color') continue;
    out.push(`        ${JSON.stringify(role)}: "var(--odp-${role})",\n`);
  }
  // The theme-color role serves the <meta name="theme-color"> tag; exposed under a short name.
  out.push('        theme: "var(--odp-theme-color)",\n');
  out.push('      },\n');

  out.push('      fontFamily: {\n');
  for (const role of Object.keys(source.fontFamilies)) {
    out.push(`        ${role}: "var(--odp-font-${role})",\n`);
  }
  out.push('      },\n');

  out.push('      fontSize: {\n');
  for (const token of Object.keys(source.typeScale)) {
    out.push(`        ${JSON.stringify(token)}: [\n`);
    out.push(`          "var(--odp-font-size-${token})",\n`);
    out.push(
      `          { lineHeight: "var(--odp-line-height-${token})", fontWeight: "var(--odp-font-weight-${token})" },\n`,
    );
    out.push('        ],\n');
  }
  out.push('      },\n');

  out.push('      spacing: {\n');
  for (const token of Object.keys(SPACING_CSS) as (keyof typeof SPACING_CSS)[]) {
    out.push(`        ${JSON.stringify(token)}: "var(--odp-${SPACING_CSS[token]})",\n`);
  }
  out.push('        button: "var(--odp-button-height)",\n');
  out.push('        input: "var(--odp-input-height)",\n');
  out.push('        icon: "var(--odp-icon-size)",\n');
  out.push('      },\n');

  out.push('      borderRadius: {\n');
  for (const [token] of Object.entries(source.radii)) {
    out.push(`        ${token}: "var(--odp-radius-${token})",\n`);
  }
  out.push('      },\n');

  out.push('      borderWidth: {\n');
  out.push(`        DEFAULT: "var(--odp-border-width)",\n`);
  out.push('      },\n');

  out.push('      boxShadow: {\n');
  for (const [token] of Object.entries(source.shadows)) {
    out.push(`        ${token}: "var(--odp-shadow-${token})",\n`);
  }
  out.push('      },\n');

  out.push(
    '\n      // Focus treatment (branding.md, Accessibility): a visible ring with offset, both tokens.\n',
  );
  out.push('      ringColor: {\n');
  out.push(`        DEFAULT: "var(--odp-focus-ring-color)",\n`);
  out.push('      },\n');
  out.push('      ringWidth: {\n');
  out.push(`        DEFAULT: "var(--odp-focus-width)",\n`);
  out.push('      },\n');
  out.push('      ringOffsetWidth: {\n');
  out.push(`        DEFAULT: "var(--odp-focus-offset)",\n`);
  out.push('      },\n');

  out.push('    },\n');
  out.push('  },\n');
  out.push('};\n\n');
  out.push('export default theme;\n');
  return out.join('');
}

/** Every generated artifact, in write order. `path` is relative to `packages/ui`. */
export function generatedArtifacts(
  source: TokenSource,
): readonly { readonly path: string; readonly content: string }[] {
  return [
    { path: 'src/styles/theme.css', content: renderThemeCss(source) },
    { path: 'src/styles/fonts.css', content: renderFontsCss(source) },
    { path: 'tailwind.preset.ts', content: renderPresetTs(source) },
  ];
}
